  protected override void Initialize() {
    this.InitSpecialTokens((int)Token.error, (int)Token.EOF);
    this.InitStates(states);
    this.InitRules(rules);
    this.InitNonTerminals(nonTerms);
  }

  protected override void DoAction(int action)
  {
#pragma warning disable 162, 1522
    switch (action)
    {
      case 4: // Anon@1 -> /* empty */
{ SetConstMode(true); }
        break;
      case 5: // file -> PRECONST, Anon@1, nc_expr
{ setConstExpr(ValueStack[ValueStack.Depth-1].expr); SetConstMode(false); }
        break;
      case 7: // def -> declaration
{ globalDataDecl(ValueStack[ValueStack.Depth-1].tree); }
        break;
      case 8: // def -> ORG, nc_expr
{ SetOrg(ValueStack[ValueStack.Depth-1].expr); }
        break;
      case 9: // def -> WORK, nc_expr
{ SetWork(ValueStack[ValueStack.Depth-1].expr); }
        break;
      case 10: // def -> OFFSET, nc_expr
{ SetOffset(ValueStack[ValueStack.Depth-1].expr); }
        break;
      case 11: // def -> PLAIN
{ procPlainString(ValueStack[ValueStack.Depth-1].str); }
        break;
      case 12: // def -> MODULE, nc_expr
{ StartModule(ValueStack[ValueStack.Depth-1].expr); }
        break;
      case 13: // def -> MODULEEND
{ EndModule(); }
        break;
      case 15: // Anon@2 -> /* empty */
{
                     funcDef(ValueStack[ValueStack.Depth-1].tree);
                     initFunc();
                     contLabel = 0;
                     breakLabel = 0;
              }
        break;
      case 16: // func_def -> func_head_decl, Anon@2, func_body
{
                     funcend(ValueStack[ValueStack.Depth-1].expr);
                     endFunc();
              }
        break;
      case 17: // Anon@3 -> /* empty */
{ funchead(); }
        break;
      case 18: // func_body -> static_declaration_list, func_begin, declaration_list, Anon@3, 
               //              stmt_list, func_end
{ CurrentSemanticValue.expr = ValueStack[ValueStack.Depth-1].expr; }
        break;
      case 20: // declaration_list -> declaration_list, declaration
{ yyerrok(); localDataDecl(ValueStack[ValueStack.Depth-1].tree, true); }
        break;
      case 22: // static_declaration_list -> static_declaration_list, declaration
{ yyerrok(); localDataDecl(ValueStack[ValueStack.Depth-1].tree, false); }
        break;
      case 24: // func_end -> end, sc
{ CurrentSemanticValue.expr = null; }
        break;
      case 25: // func_end -> end
{ CurrentSemanticValue.expr = null; }
        break;
      case 26: // func_end -> end, P_OPEN, expr, P_CLOSE, sc
{ CurrentSemanticValue.expr = ValueStack[ValueStack.Depth-3].expr; }
        break;
      case 30: // stmt -> PLAIN
{ procPlainString(ValueStack[ValueStack.Depth-1].str); }
        break;
      case 31: // stmt -> expr, sc
{ expstmt(ValueStack[ValueStack.Depth-2].expr); resetHeap(); }
        break;
      case 32: // Anon@4 -> /* empty */
{
              int label = genNewLabel(); pushIfLabel(label);
            }
        break;
      case 33: // stmt -> IF, Anon@4, then_part_list, else_part, endif
{
                     int label = popIfLabel();
                     genlabel(label);
                     var elseLabel = popElseLabel();
                     if(elseLabel >= 0)genlabel(elseLabel);
              }
        break;
      case 34: // stmt -> loop_head, stmt
{
                     genjump(ValueStack[ValueStack.Depth-2].label);
                     genlabel(ValueStack[ValueStack.Depth-2].label + 1);
                     popLabels();
              }
        break;
      case 35: // stmt -> while_head, compound_while_stmt
{
              genjump(ValueStack[ValueStack.Depth-2].label);
              genlabel(ValueStack[ValueStack.Depth-2].label + 1);
              popLabels();
       }
        break;
      case 36: // stmt -> repeat_head, until_stmt, UNTIL, expr, sc
{
                     genbool(enBool(ValueStack[ValueStack.Depth-2].expr), 0, ValueStack[ValueStack.Depth-5].label);
                     genlabel(ValueStack[ValueStack.Depth-5].label + 1);
                     popLabels();
              }
        break;
      case 37: // stmt -> EXIT, sc
{
                     if (breakLabel == 0)
                     {
                            Error("break outside loop");
                     }
                     genjump(breakLabel);
              }
        break;
      case 38: // stmt -> EXIT, P_OPEN, expr, P_CLOSE, sc
{
                     if(!ValueStack[ValueStack.Depth-3].expr.IsConst())
                     {
                            Error("exit param must be const.");
                     }
                     int brkLabel = peekBreakLabel(ValueStack[ValueStack.Depth-3].expr.ConstValue.Value - 1);
                     Console.WriteLine("brkLabel:" + brkLabel);
                     if(brkLabel >= 0)
                     {
                            genjump(brkLabel);
                     } else {
                            Error("could not exit outside loop");
                     }
              }
        break;
      case 39: // stmt -> CONTINUE, sc
{
                     if (contLabel == 0)
                     {
                            Error("continue outside loop");
                     }
                     genjump(contLabel);
              }
        break;
      case 40: // stmt -> IDENTIFIER, COLON
{
                     genStringLabel(ValueStack[ValueStack.Depth-2].symbol);
              }
        break;
      case 41: // stmt -> GOTO, IDENTIFIER
{
                     genGoto(ValueStack[ValueStack.Depth-1].symbol);
              }
        break;
      case 42: // stmt -> EXIT, TO, IDENTIFIER
{
                     genGoto(ValueStack[ValueStack.Depth-1].symbol);
              }
        break;
      case 43: // stmt -> RETURN, sc
{
                     genjump(exitLabel);
              }
        break;
      case 44: // stmt -> RETURN, expr, sc
{
                     genexp(coerce(ValueStack[ValueStack.Depth-2].expr, OperatorType.Word));
                     genjump(exitLabel);
              }
        break;
      case 45: // stmt -> PRINT, P_OPEN, str_expr_list, P_CLOSE
{ genPrint(ValueStack[ValueStack.Depth-2].tree); }
        break;
      case 46: // stmt -> case_head, begin, case_stmt_list, end
{
              doCaseEnd();
              genlabel(ValueStack[ValueStack.Depth-4].label + 1);
              popLabels();
       }
        break;
      case 47: // stmt -> for_head, for_stmt
{
                     var forIdentifier = ValueStack[ValueStack.Depth-2].forInfo.Expr;
                     var forLabel = ValueStack[ValueStack.Depth-2].forInfo.Label;
                     var forOp = ValueStack[ValueStack.Depth-2].forInfo.Op;
                     var forExpr = ValueStack[ValueStack.Depth-2].forInfo.CheckExpr;

                     genlabel(ValueStack[ValueStack.Depth-2].forInfo.Label + 1);
                     // 1è¶³ã
                     Expr one = makeNode1(Opcode.Const, OperatorType.Constant, TypeInfo.WordTypeInfo, null);
                     one.ConstValue = new ConstInfo(1);
                     genexp(expIncdec(forOp == "TO" ? Opcode.PostInc : Opcode.PostDec, forIdentifier));

                     genForloop(forOp, forIdentifier, forExpr, ValueStack[ValueStack.Depth-2].forInfo.Label);

                     genlabel(ValueStack[ValueStack.Depth-2].forInfo.Label + 2);
                     popLabels();
              }
        break;
      case 49: // case_head -> CASE, expr, of
{
              int label;
              CurrentSemanticValue.label = label = genNewLabel(); genNewLabel();
              pushLabels();
              breakLabel = label + 1;
              contLabel = label;
              genlabel(label);

              doCaseHead(ValueStack[ValueStack.Depth-2].expr);
       }
        break;
      case 54: // Anon@5 -> /* empty */
{ doCase(ValueStack[ValueStack.Depth-2].expr); }
        break;
      case 56: // Anon@6 -> /* empty */
{ doCase(null); }
        break;
      case 58: // Anon@7 -> /* empty */
{ doCase(ValueStack[ValueStack.Depth-1].expr); }
        break;
      case 60: // Anon@8 -> /* empty */
{ doCase(null); }
        break;
      case 63: // case_stmt_head -> expr
{ CurrentSemanticValue.expr = ValueStack[ValueStack.Depth-1].expr; }
        break;
      case 64: // case_stmt_head -> nc_expr, TO, nc_expr
{ CurrentSemanticValue.expr = makeNode2(Opcode.Range, OperatorType.Word, TypeInfo.WordTypeInfo, ValueStack[ValueStack.Depth-3].expr, ValueStack[ValueStack.Depth-1].expr);  }
        break;
      case 65: // repeat_head -> REPEAT
{
              int label;
              CurrentSemanticValue.label = label = genNewLabel(); genNewLabel();
              pushLabels();
              breakLabel = label + 1;
              contLabel = label;
              genlabel(label);
       }
        break;
      case 67: // Anon@9 -> /* empty */
{}
        break;
      case 72: // for_head -> FOR, IDENTIFIER, OP_EQ, nc_expr, for_to_or_downto, nc_expr
{
              CurrentSemanticValue.forInfo = new ForInfo();
              int label;

              CurrentSemanticValue.forInfo.Label = label = genNewLabel(); genNewLabel(); genNewLabel();
              CurrentSemanticValue.forInfo.Expr = expIdent(ValueStack[ValueStack.Depth-5].symbol, true);
              CurrentSemanticValue.forInfo.CheckExpr = ValueStack[ValueStack.Depth-1].expr;
              CurrentSemanticValue.forInfo.Op = ValueStack[ValueStack.Depth-2].op;

              pushLabels();
              breakLabel = label + 2;
              contLabel  = label + 1;
              genexp(expAssign(expIdent(ValueStack[ValueStack.Depth-5].symbol, true), ValueStack[ValueStack.Depth-3].expr));
              genlabel(label);
              resetHeap();
       }
        break;
      case 73: // for_to_or_downto -> TO
{ CurrentSemanticValue.op = "TO"; }
        break;
      case 74: // for_to_or_downto -> DOWNTO
{ CurrentSemanticValue.op = "DOWNTO"; }
        break;
      case 75: // loop_head -> LOOP
{
              int label;
              CurrentSemanticValue.label = label = genNewLabel() ; genNewLabel();
              pushLabels();
              breakLabel = label + 1; contLabel = label;
              genlabel(label);
              }
        break;
      case 76: // while_head -> WHILE, expr
{
              int label;
              CurrentSemanticValue.label = label = genNewLabel(); genNewLabel();
              pushLabels();
              breakLabel = label + 1; contLabel = label;
              genlabel(label);
              if(ValueStack[ValueStack.Depth-1].expr.IsValueConst() && ValueStack[ValueStack.Depth-1].expr.ConstValue.Value != 0)
              {
                     // expr no check
              } else {
                     genbool(enBool(ValueStack[ValueStack.Depth-1].expr), 0, label + 1);
              }
              resetHeap();
       }
        break;
      case 77: // then_part_list -> then_part
{ genjump(peekIfLabel()); pushElseLabel(ValueStack[ValueStack.Depth-1].label);  CurrentSemanticValue.label = ValueStack[ValueStack.Depth-1].label; }
        break;
      case 78: // then_part_list -> then_part_list, elif, then_part
{ genjump(peekIfLabel()); pushElseLabel(ValueStack[ValueStack.Depth-1].label); CurrentSemanticValue.label = ValueStack[ValueStack.Depth-1].label; }
        break;
      case 79: // then_part -> then_head, stmt, sc
{ CurrentSemanticValue.label = ValueStack[ValueStack.Depth-3].label; }
        break;
      case 80: // then_part -> then_head, stmt
{ CurrentSemanticValue.label = ValueStack[ValueStack.Depth-2].label; }
        break;
      case 81: // then_head -> expr, then
{
                     var elseLabel = popElseLabel();
                     if(elseLabel >= 0)
                     {
                            genlabel(elseLabel);
                     }
                     int label;
                     CurrentSemanticValue.label = label = genNewLabel();
                     genbool(enBool(ValueStack[ValueStack.Depth-2].expr), 0, label);
                     resetHeap();
              }
        break;
      case 83: // Anon@10 -> /* empty */
{ var elseLabel = popElseLabel(); if(elseLabel >= 0)genlabel(elseLabel); }
        break;
      case 89: // Anon@11 -> /* empty */
{ yyerrok(); }
        break;
      case 90: // compound_stmt -> begin, Anon@11, stmt_list, end
{}
        break;
      case 101: // Anon@12 -> /* empty */
{ yyerrok(); }
        break;
      case 115: // declaration -> VAR, declarator_list, sc
{ CurrentSemanticValue.tree = Tree.CreateDecl(ValueStack[ValueStack.Depth-2].tree); }
        break;
      case 116: // declaration -> ARRAY, declarator_list, sc
{ CurrentSemanticValue.tree = Tree.CreateTree2(DeclNode.Array, ValueStack[ValueStack.Depth-2].tree); }
        break;
      case 117: // declaration -> CONST, const_list, sc
{ CurrentSemanticValue.tree = Tree.CreateTree2(DeclNode.Const, ValueStack[ValueStack.Depth-2].tree); }
        break;
      case 118: // declaration -> MACHINE, func_declarator_list, sc
{ CurrentSemanticValue.tree = Tree.CreateTree2(DeclNode.Machine, ValueStack[ValueStack.Depth-2].tree); }
        break;
      case 121: // const -> IDENTIFIER, OP_EQ, expr
{ CurrentSemanticValue.tree = DefineConst(Tree.CreateDeclIdentifier(DeclNode.Id, ValueStack[ValueStack.Depth-3].symbol), ValueStack[ValueStack.Depth-1].expr); }
        break;
      case 122: // const -> IDENTIFIER, OP_EQ, begin, code_expr_list, end
{ CurrentSemanticValue.tree = DefineConst(Tree.CreateDeclIdentifier(DeclNode.Id, ValueStack[ValueStack.Depth-5].symbol), ValueStack[ValueStack.Depth-2].tree); }
        break;
      case 123: // const -> ASM, IDENTIFIER, OP_EQ, expr
{ CurrentSemanticValue.tree = DefineConst(Tree.CreateDeclIdentifier(DeclNode.Id, ValueStack[ValueStack.Depth-3].symbol), ValueStack[ValueStack.Depth-1].expr, true); }
        break;
      case 124: // const -> IDENTIFIER, error
{ Error("CONST required initial value"); }
        break;
      case 125: // declarator_list -> declarator
{ CurrentSemanticValue.tree = ValueStack[ValueStack.Depth-1].tree; }
        break;
      case 126: // declarator_list -> declarator_list, COMMA, declarator
{ CurrentSemanticValue.tree = ValueStack[ValueStack.Depth-3].tree.Append(ValueStack[ValueStack.Depth-1].tree); }
        break;
      case 127: // func_declarator_list -> func_declarator
{ CurrentSemanticValue.tree = Tree.CreateIdentifierTypeTree(TypeDataSize.Word, ValueStack[ValueStack.Depth-1].tree); }
        break;
      case 128: // func_declarator_list -> func_declarator_list, COMMA, func_declarator
{ CurrentSemanticValue.tree = ValueStack[ValueStack.Depth-3].tree.Append(Tree.CreateIdentifierTypeTree(TypeDataSize.Word, ValueStack[ValueStack.Depth-1].tree)); }
        break;
      case 129: // declarator -> byte_spec, declarator2
{ CurrentSemanticValue.tree = Tree.CreateIdentifierTypeTree(TypeDataSize.Byte, ValueStack[ValueStack.Depth-1].tree); }
        break;
      case 130: // declarator -> byte_spec, declarator2, OP_EQ, begin, code_expr_list, end
{ CurrentSemanticValue.tree = Tree.CreateIdentifierTypeTree(TypeDataSize.Byte, ValueStack[ValueStack.Depth-5].tree.SetInitialValueCode(ValueStack[ValueStack.Depth-2].tree)); }
        break;
      case 131: // declarator -> byte_spec, declarator2, OP_EQ, expr
{ CurrentSemanticValue.tree = Tree.CreateIdentifierTypeTree(TypeDataSize.Byte, ValueStack[ValueStack.Depth-3].tree.UpdateIdentifier( null, ValueStack[ValueStack.Depth-1].expr)); }
        break;
      case 132: // declarator -> word_spec, declarator2, OP_EQ, begin, code_expr_list, end
{ CurrentSemanticValue.tree = Tree.CreateIdentifierTypeTree(TypeDataSize.Word, ValueStack[ValueStack.Depth-5].tree.SetInitialValueCode(ValueStack[ValueStack.Depth-2].tree)); }
        break;
      case 133: // declarator -> word_spec, declarator2
{ CurrentSemanticValue.tree = Tree.CreateIdentifierTypeTree(TypeDataSize.Word, ValueStack[ValueStack.Depth-1].tree); }
        break;
      case 134: // declarator -> word_spec, declarator2, OP_EQ, expr
{ CurrentSemanticValue.tree = Tree.CreateIdentifierTypeTree(TypeDataSize.Word, ValueStack[ValueStack.Depth-3].tree.UpdateIdentifier(null, ValueStack[ValueStack.Depth-1].expr)); }
        break;
      case 135: // declarator -> float_spec, declarator2, OP_EQ, begin, code_expr_list, end
