        break;
      case 144: // declarator2 -> IDENTIFIER
{ CurrentSemanticValue.tree = Tree.CreateDeclIdentifier(DeclNode.Id, ValueStack[ValueStack.Depth-1].symbol); }
        break;
      case 145: // declarator2 -> declarator2, COLON, expr
{ CurrentSemanticValue.tree = ValueStack[ValueStack.Depth-3].tree.UpdateIdentifier(createExprString(ValueStack[ValueStack.Depth-1].expr, true)); }
        break;
      case 146: // declarator2 -> declarator2, AB_OPEN, B_CLOSE
{ CurrentSemanticValue.tree = Tree.CreateArray(ValueStack[ValueStack.Depth-3].tree, null);  }
        break;
      case 147: // declarator2 -> declarator2, AB_OPEN, expr, B_CLOSE
{ CurrentSemanticValue.tree = Tree.CreateArray(ValueStack[ValueStack.Depth-4].tree, ValueStack[ValueStack.Depth-2].expr);  }
        break;
      case 148: // func_head_decl -> declarator2, P_OPEN, P_CLOSE
{ CurrentSemanticValue.tree = Tree.CreateIdentifierTypeTree(TypeDataSize.Word, Tree.CreateTree3(DeclNode.Func, ValueStack[ValueStack.Depth-3].tree, null )); }
        break;
      case 149: // func_head_decl -> declarator2, P_OPEN, param_list, P_CLOSE
{ CurrentSemanticValue.tree = Tree.CreateIdentifierTypeTree(TypeDataSize.Word, Tree.CreateTree3(DeclNode.Func, ValueStack[ValueStack.Depth-4].tree, ValueStack[ValueStack.Depth-2].tree )); }
        break;
      case 150: // func_head_decl -> declarator2, P_OPEN, CONSTANT, P_CLOSE
{ CurrentSemanticValue.tree = Tree.CreateIdentifierTypeTree(TypeDataSize.Word, Tree.CreateTreeExpr(DeclNode.Func, ValueStack[ValueStack.Depth-4].tree, expConst(ValueStack[ValueStack.Depth-2].constValue,TypeDataSize.Byte))); }
